type Props = { active: boolean; company: string; user: string; personId: string; project?: Project; contextLoading: boolean; contextError?: ApiError; tail: string[]; navigationLocked: boolean; navigate: (path: string) => void; onLockedChange: (locked: boolean) => void };
type Submit = (input: PackageCommand) => Promise<PackageReply | undefined>;
