    {(props.active || command.locked) && <div className="engineering-command-state"><PackageCommandState />{notice && props.active && !denied && <MessageStrip design="Positive" hideCloseButton>{notice}</MessageStrip>}{savedId && props.active && !denied && <Button disabled={command.locked || props.navigationLocked} onClick={() => props.navigate(`${rootPath(props.project!.id)}/${savedId}`)}>Open saved work package</Button>}</div>}
    {props.active && (props.contextLoading ? <Loading label="Opening design package project…" /> : props.contextError ? <div className="page"><Failure error={props.contextError} /></div> : !props.project ? <div className="page"><Empty title="Choose a project" action={<Button onClick={() => props.navigate('/projects')}>Open projects</Button>}>Engineering work packages belong to a project.</Empty></div> : !permitted ? <div className="page"><Failure error={new ApiError('Work package access is unavailable.', 'capability_denied', 403)} /></div> : denied ? <div className="page"><MessageStrip hideCloseButton>Current access changed. Previous package and source content is hidden.</MessageStrip><Button disabled={command.locked} onClick={() => { setDenied(false); setRevision(value => value + 1); }}>Recheck work package access</Button></div> : <PackageWorkspace key={authority} {...props} project={props.project} submit={submit} revision={revision} locked={command.locked || props.navigationLocked} onDenied={() => setDenied(true)} packetId={packetId} setPacketId={setPacketId} />)}
