  const ready = title.trim() && reason.trim() && reviewed && (kind === 'basis' ? criteria.trim() && (sources.drawings.length || sources.citations.length || sources.artifacts.length) : kind === 'calculation' ? inputKeys.length && sources.artifacts.length && algorithm.trim() && tool.trim() && toolVersion.trim() && explanation.trim() : calculationIds.length && deliverableType.trim() && description.trim() && (sources.artifacts.length || sources.drawings.length || sources.citations.length));
